public static RMarketConditionTable find(RMarketConditionRelation   _relation,
                                         RefRecId                   _refRecId,
                                         int                        _num,
                                         boolean                    _forUpdate = false)
{
    RMarketConditionTable condition;
    ;
    condition.selectForUpdate(_forUpdate);

    if (_refRecId)
    {
        select firstonly condition
            where condition.Relation  == _relation
               && condition.RefRecId  == _refRecId
               && condition.Num       == _num;
    }

    return condition;
}

public static boolean exists(RMarketConditionRelation   _relation,
                             RefRecId                   _refRecId,
                             int                        _num,
                             boolean                    _forUpdate = false)
{
    boolean res;
    ;
    res = _refRecId && (select firstonly RecId from RMarketConditionTable
                         where RMarketConditionTable.Relation  == _relation
                            && RMarketConditionTable.RefRecId  == _refRecId
                            && RMarketConditionTable.Num       == _num).RecId != 0;

    return res;
}

public static RMarketConditionTable findRecId(RecId      _recId,
                                              boolean    _forUpdate = false)
{
    RMarketConditionTable condition;
    ;
    if (_recId)
    {
        condition.selectForUpdate(_forUpdate);

        select firstonly condition
            where condition.RecId  == _recId;
    }

    return condition;
}

public void conditionNumDecrease()
{
    RMarketConditionTable other = RMarketConditionTable::find(this.Relation, this.RefRecId, this.Num - 1, true);
    if (other)
        RMarketConditionTable::conditionwapNum(this, other);
    else
    {
        ttsbegin;
        this.Num -= 1;
        if (this.validateWrite())
            this.update();
        ttscommit;
    }
}

public void conditionNumRaise()
{
    RMarketConditionTable other = RMarketConditionTable::find(this.Relation, this.RefRecId, this.Num + 1, true);
    if (other)
        RMarketConditionTable::conditionwapNum(this, other);
    else
    {
        ttsbegin;
        this.Num += 1;
        if (this.validateWrite())
            this.update();
        ttscommit;
    }
}

public static void conditionwapNum(RMarketConditionTable _condition1, RMarketConditionTable _condition2)
{
    int actionNum = _condition1.Num;

    ttsbegin;
    _condition1.Num = _condition2.Num;

    _condition2.Num = maxInt();
    if (_condition2.validateWrite())
        _condition2.Update();
    _condition2.Num = actionNum;

    if (_condition1.validateWrite())
        _condition1.update();

    if (_condition2.validateWrite())
        _condition2.update();
    ttscommit;
}

public boolean calc(RMarketSubAccount _subAccount, RMarketTimestamp _tsCursor)
{
    boolean ret;
    real value  = this.calcValue(_subAccount, _tsCursor);
    real value2 = this.calcValue2(_subAccount, _tsCursor);

    switch (this.ComparisonType)
    {
        case RMarketConditionComparisonType::Equal:
            ret = (value == value2);
            break;
        case RMarketConditionComparisonType::Less:
            ret = (value <  value2);
            break;
        case RMarketConditionComparisonType::LessOrEqual:
            ret = (value <= value2);
            break;
        case RMarketConditionComparisonType::More:
            ret = (value >  value2);
            break;
        case RMarketConditionComparisonType::MoreOrEqual:
            ret = (value >= value2);
            break;
        default:
            throw error(strFmt("Comparison type %1 isn't implemented yet!", enum2Str(this.ComparisonType)));
    }
    return ret;
}

